sections.code:
/* Universal selector: targets every element */
* {
  box-sizing: border-box;
}

/* Element selector: all paragraphs */
p {
  font-size: 16px;
  color: #464554;
}

/* Class selector: elements with class="btn" */
.btn {
  background-color: #00629d;
  color: #ffffff;
  border-radius: 8px;
}

/* ID selector: element with id="main-header" */
#main-header {
  font-size: 28px;
  font-weight: bold;
}

/* Descendant combinator: p inside article */
article p {
  line-height: 1.6;
}

/* Child combinator: direct li children of ul */
ul > li {
  list-style-type: square;
}

/* Grouping selectors */
h1, h2, h3 {
  font-family: 'Inter', sans-serif;
}

.box {
  /* Set box-sizing so width includes padding & border */
  box-sizing: border-box;
  width: 300px;
  height: 200px;

  /* Inner spacing */
  padding: 20px;

  /* Border */
  border: 2px solid #00629d;

  /* Outer spacing */
  margin: 16px;
}
